"""All Ipsec Exceptions here"""


class IpSecException(Exception):
    """All Ipsec Exceptions here"""
    pass


class IpSecValidationError(IpSecException):
    """ Raises error if validation for connection status fails"""


class IpSecConnectionError(IpSecException):
    """ Raises error if there are connection issues"""


class IpSecDisabledError(IpSecException):
    """ Raises error if Ipsec is disabled"""


class IpSecStateError(IpSecException):
    """ Raises error if Ipsec state is not as expected"""


class EmergencyBypassStateError(IpSecException):
    """ Raises error if Emergency bypass state is not as expected"""
